INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Can We Start Over?', 'She returns to her hometown after a decade away and moves in with an old friend. Their reunion reminds her of just how comfortable his presence is and how close they''ve always been. Little by little, she reclaims old dreams, builds new ones, and falls in love with the one that was always meant to be.' FROM games WHERE igdb_id = 321777 ON CONFLICT (game_id, language_code) DO NOTHING;
