INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Signal Control Simulator', 'The job of a "signal worker" is to protect the safety of Japan''s railways behind the scenes. Operate the interlocking panels to safely and accurately operate trains that run in seconds. You can experience the work of a signal attendant, which is essential for safe railway operation.' FROM games WHERE igdb_id = 312424 ON CONFLICT (game_id, language_code) DO NOTHING;
