INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ashes: Hard Reset', 'Ashes: Hard Reset is the prequel expansion for Ashes: Afterglow and is a linear campaign in the style of 2063. Take the role of the veteran scav Walker as he guides a team of elite soldiers into The City. As events spiral out of control Walker finds out that a long forgotten foe has caught up with him... and that not all injuries are of the flesh.' FROM games WHERE igdb_id = 305124 ON CONFLICT (game_id, language_code) DO NOTHING;
