INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Truck Simulator 25: American Driver', 'Truck Simulator 25 - American Driver invites you to an exciting adventure on the roads of America, progressing through levels set in diverse locations — from industrial zones to quiet suburbs and the bustling city center. From hauling cargo across diverse landscapes to managing your trucking business, this game brings the thrill of the road to life. Your task is to deliver goods on time, improving your driving skills and upgrading your trucks as you go.' FROM games WHERE igdb_id = 325790 ON CONFLICT (game_id, language_code) DO NOTHING;
