INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ultimate General: American Revolution', 'American Revolution is a sandbox strategy game featuring the epic historical period during the rebellion of the American colonies against the British Empire. Take on the role of the British or American Colonists, and fight for territorial control over North America. A gripping real-time campaign awaits you on a detailed 3d map where you can build your army and navy, construct military infrastructure, and fully command your armies on a regimental level. If you want even more action you can fully zoom-in and fight massive battles on a battalion level.' FROM games WHERE igdb_id = 277111 ON CONFLICT (game_id, language_code) DO NOTHING;
