INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'All You Need is Help', 'Dive into a quirky multiplayer co-op puzzle game where adorable, fluffy cube-shaped creatures collaborate to reach their goals. These creatures, each oddly shaped, jostle against each other to help solve puzzles together. When in trouble, shout "HELP!" and friends will surely come to your aid. With everyone''s strength, turn friendships into friend-shapes!
